const fs = require('fs');

const input = JSON.parse(fs.readFileSync('last_user_input.json', 'utf8'));
const content = input.content;

const diffMatch = content.match(/\[diff_block_start\]([\s\S]*?)\[diff_block_end\]/);
if (!diffMatch) {
    console.log('No diff block found!');
    process.exit(1);
}

const diffText = diffMatch[1];
const diffLines = diffText.split('\n');

console.log('Total diff lines:', diffLines.length);

// Extract the original file from the diff:
// Lines that start with '-' were in the original file (remove the leading '-').
// Lines that start with ' ' were unchanged in the original file (remove the leading ' ').
// Lines that start with '+' were added by the user (ignore for original).
// Header lines (like @@ ... @@) are skipped.

const originalLines = [];
for (let i = 0; i < diffLines.length; i++) {
    const line = diffLines[i];
    if (line.startsWith('@@')) continue;
    if (line.startsWith('-')) {
        originalLines.push(line.slice(1));
    } else if (line.startsWith('+')) {
        // added line, ignore for original
    } else if (line.startsWith(' ')) {
        originalLines.push(line.slice(1));
    }
}

console.log('Reconstructed original lines count:', originalLines.length);
fs.writeFileSync('reconstructed_Game.js', originalLines.join('\n'));
console.log('First 5 lines of reconstructed:');
console.log(originalLines.slice(0, 5).join('\n'));
console.log('Last 10 lines of reconstructed:');
console.log(originalLines.slice(-10).join('\n'));
